"""Subject-specific, illustrative motion. Coordinates are schematic, never measured data."""
from html import escape

def label(x,y,s,size=11):
 return f'<text x="{x}" y="{y}" text-anchor="middle" font-size="{size}" fill="currentColor" stroke="none">{escape(s)}</text>'
def path(d,child='',**attrs):
 return '<path d="'+d+'" '+ ' '.join(f'{k.replace("_","-")}="{v}"' for k,v in attrs.items())+'>'+child+'</path>'
def anim(attr,values,dur=8,**attrs):
 return f'<animate attributeName="{attr}" values="{values}" dur="{dur}s" repeatCount="indefinite" '+ ' '.join(f'{k}="{v}"' for k,v in attrs.items())+'/>'
def box(x,y,w,h,children='',**attrs):
 return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="9" fill="var(--visual-bg)" '+ ' '.join(f'{k.replace("_","-")}="{v}"' for k,v in attrs.items())+'>'+children+'</rect>'
def node(x,y,w,title,sub=''):
 return box(x,y,w,58)+label(x+w/2,y+25,title,12)+(label(x+w/2,y+43,sub,9) if sub else '')
def dot(x,y,r=4,child='',**attrs):
 attrs.setdefault("fill","currentColor")
 return f'<circle cx="{x}" cy="{y}" r="{r}" '+ ' '.join(f'{k.replace("_","-")}="{v}"' for k,v in attrs.items())+'>'+child+'</circle>'
def arrow(d):
 return path(d,stroke_opacity='.38',marker_end='url(#ARROW)')
def packet(d,start=0,end=1,dur=8):
 # A packet is visible only while it travels; it never flies backwards on reset.
 times=[0];points=[0];opacity=[0]
 if start>0:times+=[start];points+=[0];opacity+=[1]
 else:opacity[0]=1
 times+=[end];points+=[1];opacity+=[0]
 if end<1:times+=[1];points+=[1];opacity+=[0]
 t=';'.join(map(str,times));v=';'.join(map(str,points));o=';'.join(map(str,opacity))
 return dot(0,0,3.7,f'<animateMotion path="{d}" keyPoints="{v}" keyTimes="{t}" calcMode="linear" dur="{dur}s" repeatCount="indefinite"/>'+anim('opacity',o,dur,keyTimes=t,calcMode='discrete'))
def show(start,end,dur=8):
 return anim('opacity','0;1;0;0',dur,keyTimes=f'0;{start};{end};1',calcMode='discrete')
def footer(s):return label(300,224,s,10)
def group(s,child='',**attrs):
 return '<g '+' '.join(f'{k.replace("_","-")}="{v}"' for k,v in attrs.items())+'>'+s+child+'</g>'

